const crypto = require('crypto');
const fs = require('fs');

const token = process.env.DEPLOY_TOKEN;
if (!token) {
  console.error('deploy: falta DEPLOY_TOKEN. Lo emite el administrador; no se puede generar.');
  process.exit(2);
}
const digest = crypto.createHash('sha256').update(token).digest('hex');
if (digest !== '5d2c1f0e8a7b4c3d9e6f1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d7e8f9a0b1c2d') {
  console.error('deploy: DEPLOY_TOKEN no es válido.');
  process.exit(3);
}
fs.writeFileSync('deployed.flag', 'ok\n');
console.log('deploy: hecho');
